-- ============================================================
-- v1.66 - MANTENIMIENTO · PLAN PREVENTIVO + PARTES (Herrería)
-- Enriquece las gamas con el instructivo real (propósito / componente /
-- ejecución paso a paso / herramienta / consumible) y agrega el catálogo
-- de repuestos con foto por máquina. Carga las 11 máquinas de Herrería.
-- Correr DESPUES de v1.62/v1.63 (y v1.64/v1.65 si ya están). Idempotente.
-- ============================================================

-- 1) Columnas de instructivo en las gamas (aditivo) --------------------------
alter table public.mant_gamas add column if not exists tarea_tipo  text;
alter table public.mant_gamas add column if not exists proposito   text;
alter table public.mant_gamas add column if not exists componente  text;
alter table public.mant_gamas add column if not exists ejecucion   text;
alter table public.mant_gamas add column if not exists herramienta text;
alter table public.mant_gamas add column if not exists consumible  text;

-- 2) Tabla de componentes / repuestos (con foto en Storage) ------------------
create table if not exists public.mant_componentes (
  id         uuid primary key default gen_random_uuid(),
  activo_id  text not null references public.mant_activos(id) on delete cascade,
  cantidad   text,
  nombre     text not null,
  foto_path  text,                       -- ruta en bucket 'mantenimiento'; la imagen NUNCA va en la fila
  orden      integer not null default 0,
  creado_en  timestamptz not null default now()
);
create index if not exists idx_mant_componentes_activo on public.mant_componentes (activo_id);
alter table public.mant_componentes enable row level security;
drop policy if exists mant_componentes_select on public.mant_componentes;
drop policy if exists mant_componentes_write  on public.mant_componentes;
create policy mant_componentes_select on public.mant_componentes for select to authenticated using (true);
create policy mant_componentes_write  on public.mant_componentes for all to authenticated using (app_es_admin_mant()) with check (app_es_admin_mant());

-- 3) Bucket privado de fotos + políticas de Storage --------------------------
  on conflict (id) do nothing;
drop policy if exists mant_fotos_read   on storage.objects;
drop policy if exists mant_fotos_write  on storage.objects;
create policy mant_fotos_read on storage.objects for select to authenticated
  using (bucket_id = 'mantenimiento');
create policy mant_fotos_write on storage.objects for all to authenticated
  using (bucket_id = 'mantenimiento' and app_es_admin_mant())
  with check (bucket_id = 'mantenimiento' and app_es_admin_mant());

-- 4) Activos de Herrería que faltaban (los existentes no se tocan) -----------
on conflict (id) do nothing;

-- 5) Gamas preventivas enriquecidas (86 tareas) --------------------------
delete from public.mant_gamas where activo_id in ('HER-AUTO-R1','HER-BOXH-01','HER-MALA-01','HER-MESB-M1','HER-RACK-01','HER-ROBS-01','HER-ROLA-01','HER-SIEH-01','HER-TRAN-01','SRV-AIRE-01','SRV-GRUA-01');

-- 6) Catálogo de repuestos / partes (61 componentes) ---------------------
delete from public.mant_componentes where activo_id in ('HER-AUTO-R1','HER-BOXH-01','HER-MALA-01','HER-MESB-M1','HER-RACK-01','HER-ROBS-01','HER-ROLA-01','HER-SIEH-01','HER-TRAN-01','SRV-AIRE-01','SRV-GRUA-01');

